corrected_code:
package handlers

import (
	"encoding/json"
	"net/http"

	"github.com/go-chi/chi/v5"
	"myapp/auth"
	"myapp/models"
	"myapp/repository"
)

type PrescriptionHandler struct {
	Repo repository.PrescriptionRepository
}

func (h *PrescriptionHandler) DownloadPrescription(w http.ResponseWriter, r *http.Request) {
	prescriptionID := chi.URLParam(r, "prescriptionID")
	currentUser, ok := auth.UserFromContext(r.Context())
	if !ok {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	rx, err := h.Repo.FindByIDAndPatientID(r.Context(), prescriptionID, currentUser.ID)
	if err != nil {
		http.Error(w, "Prescription not found or access denied", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(rx)
}
